import {escapeHTML as e} from './core.js';
import {CHORDS} from './data.js';
const colors={1:'#b56544',2:'#71894f',3:'#7e6c9f',4:'#4b8196'};
export function neckDiagram(name,lefty=false,mini=false){
 const c=CHORDS[name]||CHORDS[({'A#':'Bb','D#':'Eb'}[name])];
 if(!c)return `<div class="shape-unavailable"><strong>${e(name)}</strong><p>No finger diagram saved for this transposed chord. Try the original sheet key.</p></div>`;
 const strings=['g','C','E','A'],order=lefty?[3,2,1,0]:[0,1,2,3],xs=[65,121,177,233],top=118,spacing=41;
 const description=c.frets.map((f,i)=>`${strings[i]} string ${f===0?'open':`fret ${f}, finger ${c.fingers[i]}`}`).join('; '),barres=[];
 for(const finger of [1,2,3,4]){
  const positions=order.map((s,i)=>({s,i})).filter(({s})=>c.frets[s]>0&&c.fingers[s]===finger);
  if(positions.length>1&&positions.every(({s})=>c.frets[s]===c.frets[positions[0].s])){const a=positions[0],b=positions.at(-1),y=top+(c.frets[a.s]-.5)*spacing;barres.push(`<rect data-barre="${finger}" x="${xs[a.i]-14}" y="${y-14}" width="${xs[b.i]-xs[a.i]+28}" height="28" rx="14" fill="${colors[finger]}" stroke="#fff9e6" stroke-width="1.5"/>`);}
 }
 return `<svg class="finger-diagram neck-diagram ${mini?'mini':''}" viewBox="0 0 290 360" role="img" aria-label="${e(c.label)}, ${lefty?'left':'right'} handed: ${e(description)}. Ukulele headstock and nut shown above five frets."><path d="M47 8Q149 -1 251 8L248 75 242 113H56L50 75Z" fill="#794a32" stroke="#593724" stroke-width="2"/><path d="M59 14Q149 7 239 14" fill="none" stroke="#bb8053" stroke-width="1.5"/><path d="M49 115H249V325H49Z" fill="#3b2119" stroke="#8e603e" stroke-width="2"/><g stroke="#744b30" stroke-width="1" opacity=".35"><path d="M82 118v207M108 118v207M155 118v207M205 118v207M240 118v207"/></g><g fill="#c9c6b4" stroke="#918e7e" stroke-width="1">${[26,51].map(y=>`<path d="M50 ${y}H34M248 ${y}h16"/><ellipse cx="28" cy="${y}" rx="7" ry="9"/><ellipse cx="270" cy="${y}" rx="7" ry="9"/><circle cx="79" cy="${y}" r="6"/><circle cx="219" cy="${y}" r="6"/>`).join('')}</g><circle cx="149" cy="${top+4.5*spacing}" r="5.5" fill="#d6d0b8" opacity=".65"/>${[1,2,3,4,5].map(n=>`<path d="M49 ${top+n*spacing}H249" stroke="#c9c4ae" stroke-width="2"/>`).join('')}<rect data-part="nut" x="48" y="110" width="202" height="9" rx="1" fill="#f2e4c2" stroke="#b8a78d" stroke-width="1"/>${order.map((s,i)=>`<path data-string="${4-s}" d="M${i<2?79:219} ${i===0||i===3?26:51}L${xs[i]} 113V324" fill="none" stroke="#f8f4df" stroke-width="${[1.6,2.7,2.2,1.4][s]}"/>`).join('')}<g font-family="DM Sans,sans-serif" text-anchor="middle">${order.map((s,i)=>`<rect x="${xs[i]-13}" y="67" width="26" height="20" rx="4" fill="#794a32"/><text x="${xs[i]}" y="83" font-size="17" font-weight="700" fill="#fff4d8">${strings[s]}</text>${c.frets[s]===0?`<circle cx="${xs[i]}" cy="99" r="5" fill="#794a32" stroke="#f3e3bc" stroke-width="1.7"/>`:''}`).join('')}${[1,2,3,4,5].map(n=>`<text x="28" y="${top+(n-.5)*spacing+4}" font-size="11" fill="#8c8878">${n}</text>`).join('')}</g>${barres.join('')}${order.map((s,i)=>c.frets[s]>0?`<circle cx="${xs[i]}" cy="${top+(c.frets[s]-.5)*spacing}" r="16" fill="${colors[c.fingers[s]]}" stroke="#fff5da" stroke-width="2"/><text x="${xs[i]}" y="${top+(c.frets[s]-.5)*spacing+5.7}" fill="#fffdf7" font-family="DM Sans,sans-serif" font-size="18" font-weight="700" text-anchor="middle">${c.fingers[s]}</text>`:'').join('')}<text x="149" y="349" text-anchor="middle" fill="#8a8979" font-family="DM Sans,sans-serif" font-size="9">○ open string · numbers are fingers · fret 1 below the nut</text></svg>`;
}
